#!/usr/bin/env node
// Reads every sql/migration_*.sql (plus sql/schema.sql) and works out which
// tables and columns the live database should have, then writes:
//   js/schema-expected.js   - used by the in-app "database update needed" check
//   sql/check_schema.sql    - read-only query to paste into the Supabase SQL Editor
// Run:  node tools/gen-schema-expected.js
// `--check` exits 1 if the generated files are out of date (used by CI).
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..');
const sqlDir = path.join(root, 'sql');

function strip(sql) {
  return sql.replace(/\/\*[\s\S]*?\*\//g, '').replace(/--[^\n]*/g, '');
}
const files = ['schema.sql'].concat(
  fs.readdirSync(sqlDir).filter(f => /^(migration_|fix_).*\.sql$/.test(f)).sort());
const tables = {}; // name -> Set(columns)
const ensure = t => (tables[t] = tables[t] || new Set());
const ident = '"?([a-z_][a-z0-9_]*)"?';

for (const f of files) {
  const sql = strip(fs.readFileSync(path.join(sqlDir, f), 'utf8'));
  let m;
  // create table [if not exists] t ( ...columns... );
  const ct = /create\s+table\s+(?:if\s+not\s+exists\s+)?(?:public\.)?"?([a-z_][a-z0-9_]*)"?\s*\(([\s\S]*?)\n\)\s*;/gi;
  while ((m = ct.exec(sql))) {
    const set = ensure(m[1].toLowerCase());
    let depth = 0, cur = '', parts = [];
    for (const ch of m[2]) {
      if (ch === '(') depth++; if (ch === ')') depth--;
      if (ch === ',' && depth === 0) { parts.push(cur); cur = ''; } else cur += ch;
    }
    parts.push(cur);
    for (const part of parts) {
      const c = part.trim().match(new RegExp('^' + ident + '\\s+\\S'));
      if (c && !/^(primary|foreign|unique|check|constraint|like|exclude)$/i.test(c[1])) set.add(c[1].toLowerCase());
    }
  }
  // alter table t add column [if not exists] c ...   (several per statement allowed)
  const at = /alter\s+table\s+(?:only\s+)?(?:if\s+exists\s+)?(?:public\.)?"?([a-z_][a-z0-9_]*)"?\s+([^;]*);/gi;
  while ((m = at.exec(sql))) {
    const t = m[1].toLowerCase(), body = m[2];
    const add = /add\s+column\s+(?:if\s+not\s+exists\s+)?"?([a-z_][a-z0-9_]*)"?/gi; let a;
    while ((a = add.exec(body))) ensure(t).add(a[1].toLowerCase());
    const drop = /drop\s+column\s+(?:if\s+exists\s+)?"?([a-z_][a-z0-9_]*)"?/gi; let d;
    while ((d = drop.exec(body))) ensure(t).delete(d[1].toLowerCase());
    const ren = /rename\s+column\s+"?([a-z_][a-z0-9_]*)"?\s+to\s+"?([a-z_][a-z0-9_]*)"?/gi; let r;
    while ((r = ren.exec(body))) { ensure(t).delete(r[1].toLowerCase()); ensure(t).add(r[2].toLowerCase()); }
  }
  // 'drop table' is deliberately ignored: those migrations say to re-create the
  // table from schema.sql straight afterwards, so schema.sql's definition stands.
}
const out = {};
Object.keys(tables).sort().forEach(t => { if (tables[t].size) out[t] = [...tables[t]].sort(); });

// Columns the public key is deliberately NOT allowed to read after the security
// lockdown (migration_security_1b). The in-app check must not probe them or it
// would report them "missing". The SQL check below still covers them.
const SECRET = { staff: ['pin', 'pin_hash', 'security_answer_1', 'security_answer_2', 'security_answer_1_hash', 'security_answer_2_hash', 'pin_failed_attempts', 'pin_locked_until'] };
const outApp = {};
Object.keys(out).forEach(t => { outApp[t] = out[t].filter(c => !(SECRET[t] || []).includes(c)); });

const js = `// GENERATED by tools/gen-schema-expected.js from sql/*.sql - do not edit by hand.
// Used by App._checkSchemaHealth() to tell a superuser when a database migration was never run.
window.SCHEMA_EXPECTED = ${JSON.stringify(outApp, null, 1)};
`;
const pairs = [];
Object.keys(out).forEach(t => out[t].forEach(c => pairs.push(`  ('${t}','${c}')`)));
const sqlOut = `-- GENERATED by tools/gen-schema-expected.js - read-only, safe to run any time.
-- Paste into the Supabase SQL Editor. It lists every table or column the app
-- expects but the database does not have. NO ROWS = the database is up to date.
-- If rows come back, run the matching sql/migration_*.sql file(s) and run this again.
with expected(table_name, column_name) as (values
${pairs.join(',\n')}
)
select e.table_name, e.column_name,
       case when t.table_name is null then 'table missing' else 'column missing' end as problem
from expected e
left join information_schema.tables t
  on t.table_schema = 'public' and t.table_name = e.table_name
left join information_schema.columns c
  on c.table_schema = 'public' and c.table_name = e.table_name and c.column_name = e.column_name
where c.column_name is null
order by e.table_name, e.column_name;
`;
const jsPath = path.join(root, 'js', 'schema-expected.js'), sqlPath = path.join(sqlDir, 'check_schema.sql');
if (process.argv.includes('--check')) {
  const same = fs.existsSync(jsPath) && fs.readFileSync(jsPath, 'utf8') === js && fs.existsSync(sqlPath) && fs.readFileSync(sqlPath, 'utf8') === sqlOut;
  if (!same) { console.error('schema-expected.js / check_schema.sql are out of date. Run: node tools/gen-schema-expected.js'); process.exit(1); }
  console.log('schema expectations up to date'); process.exit(0);
}
fs.writeFileSync(jsPath, js); fs.writeFileSync(sqlPath, sqlOut);
console.log(`wrote ${Object.keys(out).length} tables, ${pairs.length} columns`);
